fun averageScores(teamScores: Map<String, List<Int>>): Map<String, Double> {
    val result = mutableMapOf<String, Double>()
    for ((team, scores) in teamScores) {
        result[team] = scores.sum().toDouble() / scores.size
    }
    return result
}

