import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testSingleTeam() {
        val result = averageScores(mapOf("Tribots" to listOf(40, 60)))
        Assert.assertEquals(50.0, result["Tribots"]!!, 0.001)
    }

    @Test
    fun testMultipleTeams() {
        val result = averageScores(mapOf(
            "Tribots" to listOf(45, 72, 38),
            "RoboCats" to listOf(91, 55)
        ))
        Assert.assertEquals(51.666, result["Tribots"]!!, 0.01)
        Assert.assertEquals(73.0, result["RoboCats"]!!, 0.001)
    }

    @Test
    fun testSingleScore() {
        val result = averageScores(mapOf("Tribots" to listOf(100)))
        Assert.assertEquals(100.0, result["Tribots"]!!, 0.001)
    }

    @Test
    fun testEmptyMap() {
        val result = averageScores(emptyMap())
        Assert.assertTrue(result.isEmpty())
    }
}
